// The frozen task: a marble run on a desk. Nothing a model writes can change this file's numbers.
// Units are metres, seconds and kilograms. The desk top is the plane y = 0.

export const TASK = {
  name: 'desk-marble-run',
  goal: 'Build a marble run on an office desk that carries a dropped marble into the cup, even when the table gets bumped.',
  desk: { minX: -1.0, maxX: 1.0, minZ: -0.5, maxZ: 0.5 },
  bounds: { minX: -1.1, maxX: 1.1, minY: 0.0, maxY: 1.2, minZ: -0.6, maxZ: 0.6 },
  marble: { radius: 0.025, mass: 0.05, start: [-0.85, 0.8, -0.3] },
  cup: { center: [0.8, 0, 0.3], innerRadius: 0.07, wallHeight: 0.06, wallThickness: 0.012, segments: 20 },
  duration: 12.0,      // seconds simulated per trial; success is judged at the end
  dt: 1 / 480,         // fixed physics step
  budget: { pieces: 24, movers: 2, minSize: 0.012, maxSize: 0.9 },
};

// Deterministic PRNG (mulberry32), so a seed always gives the same trial on every machine.
export function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// One trial: where the marble is dropped, how it moves, how grippy and bouncy the run is, and when the desk is bumped.
export function trial(seed) {
  const r = rng(seed * 7919 + 17);
  const u = (lo, hi) => lo + (hi - lo) * r();
  const angle = u(0, 2 * Math.PI);
  const kick = u(0.1, 0.5);
  return {
    seed,
    startOffset: [u(-0.03, 0.03), 0, u(-0.03, 0.03)],
    startVelocity: [u(-0.15, 0.15), 0, u(-0.15, 0.15)],
    friction: u(0.02, 0.3),
    restitution: u(0.05, 0.45),
    bump: { time: u(0.5, 8.0), dv: [kick * Math.cos(angle), u(0, 0.2), kick * Math.sin(angle)] },
  };
}

// Fixed public splits. The held-out test split is derived from a secret only the final judge holds.
// VALIDATION_SEEDS_START (removed from the reproducers' copy of this file)
const VAL = (() => { const r = rng(20261025); return Array.from({ length: 16 }, () => 1000 + Math.floor(r() * 9e8)); })();
// VALIDATION_SEEDS_END
export const SPLITS = {
  val: typeof VAL === 'undefined' ? [] : VAL,
  smoke: [101, 102, 103, 104],
};

export function heldoutSeeds(secret, n = 64) {
  let h = 2166136261;
  for (const ch of String(secret)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
  const r = rng(h);
  return Array.from({ length: n }, () => 100000 + Math.floor(r() * 1e9));
}

// Camera angles the explorer's critic sees (validation views). Held-out views are chosen elsewhere.
export const VAL_CAMERAS = [
  { name: 'overview', position: [1.6, 1.3, 1.6], target: [0, 0.3, 0] },
  { name: 'closeup', position: [0.35, 0.45, 0.75], target: [0.6, 0.1, 0.2] },
  { name: 'low', position: [0.0, 0.08, 1.4], target: [0, 0.15, 0] },
  { name: 'top', position: [0.0, 2.4, 0.01], target: [0, 0, 0] },
];

#!/usr/bin/env node
// Command line for the trials: node run.mjs <scene.js> --split val|smoke|test | --seeds 5,6,7 [--json out.json] [--record]
// The test split needs HELDOUT_SECRET in the environment; sandboxes never get it.
import { writeFileSync } from 'node:fs';
import { SPLITS, heldoutSeeds } from './task.mjs';
import { loadScene, runSeeds } from './sim.mjs';
import { SceneError } from './world.mjs';

const args = process.argv.slice(2);
const opt = (name, dflt) => { const i = args.indexOf(name); return i >= 0 ? args[i + 1] : dflt; };
const file = args.find((a) => !a.startsWith('--') && !args[args.indexOf(a) - 1]?.startsWith('--'));
const split = opt('--seeds') ? 'custom' : opt('--split', 'val');
if (!file) { console.error('usage: node run.mjs <scene.js> --split val|smoke|test [--json out.json] [--record]'); process.exit(2); }

let seeds;
if (opt('--seeds')) seeds = opt('--seeds').split(',').map(Number).filter(Number.isFinite);
else if (split === 'test') {
  if (!process.env.HELDOUT_SECRET) { console.error('the test split is held out: HELDOUT_SECRET is not set'); process.exit(2); }
  seeds = heldoutSeeds(process.env.HELDOUT_SECRET);
} else if (SPLITS[split] && SPLITS[split].length) seeds = SPLITS[split];
else { console.error(`unknown split ${split}`); process.exit(2); }

const t0 = Date.now();
let out;
try {
  const build = await loadScene(file);
  out = { scene: file, split, valid: true, ...runSeeds(build, seeds, { record: args.includes('--record') }) };
} catch (e) {
  if (!(e instanceof SceneError)) throw e;
  out = { scene: file, split, valid: false, error: e.message, passed: 0, total: seeds.length, rate: 0, results: [] };
}
out.seconds = +((Date.now() - t0) / 1000).toFixed(1);
if (opt('--json')) writeFileSync(opt('--json'), JSON.stringify(out));
if (!out.valid) { console.log(`INVALID SCENE: ${out.error}`); process.exit(1); }
console.log(`${split}: ${out.passed}/${out.total} trials ended in the cup (${out.seconds}s)`);
if (split !== 'test') for (const r of out.results) {
  console.log(`  seed ${r.seed}: ${r.success ? 'IN CUP' : r.fell ? 'fell off the desk' : 'missed'}; final [${r.final}] ${r.distToCup} m from cup centre`);
}

#!/usr/bin/env node
// Renders a scene in headless Chromium: still screenshots from camera angles, optionally a replay video.
// node shoot.mjs <scene.js> --out dir [--seed 1] [--cams overview,closeup,low,top | "az,el,dist;..."] [--t end] [--trail] [--video]
import { createServer } from 'node:http';
import { readFile, mkdir, rename } from 'node:fs/promises';
import { resolve, relative, extname, join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const opt = (n, d) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : d; };
const scene = resolve(args[0]);
const out = resolve(opt('--out', 'shots'));
const seed = opt('--seed', '1');
const cams = (opt('--cams', 'overview,closeup,low,top')).split(/[;|]/).flatMap((c) => (c.includes(',') && c.split(',').length === 3 ? [c] : c.split(',')));
const at = opt('--t', 'end');
const bump = opt('--bump', '');
const W = +opt('--w', 1280), H = +opt('--h', 720);

const TYPES = { '.html': 'text/html', '.mjs': 'text/javascript', '.js': 'text/javascript', '.json': 'application/json' };
// Serve the repository root plus the scene file itself under /scene/<name>, wherever it lives.
const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  try {
    const file = url.pathname.startsWith('/scene/') ? scene : join(ROOT, decodeURIComponent(url.pathname));
    if (!file.startsWith(ROOT) && file !== scene) throw new Error('outside root');
    const body = await readFile(file);
    res.writeHead(200, { 'content-type': TYPES[extname(file)] || 'application/octet-stream', 'cache-control': 'no-store' });
    res.end(body);
  } catch { res.writeHead(404); res.end(); }
}).listen(0, '127.0.0.1');
await new Promise((r) => server.on('listening', r));
const base = `http://127.0.0.1:${server.address().port}/harness/view.html`;
const sceneParam = '/scene/' + encodeURIComponent(relative(ROOT, scene).replace(/[\\/]/g, '_'));

const browser = await chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
await mkdir(out, { recursive: true });
const report = { scene: args[0], seed: +seed, shots: [] };
const trail = args.includes('--trail') ? { trail: 1 } : {};
const qs = (extra) => new URLSearchParams({ scene: sceneParam, seed, w: W, h: H, ...trail, ...(bump ? { bump } : {}), ...extra }).toString();
const waitReady = async (page, flag) => {
  await page.waitForFunction((f) => window[f] || window.__error, flag, { timeout: 180000 });
  const err = await page.evaluate(() => window.__error);
  if (err) throw new Error(err);
};
try {
  const page = await browser.newPage({ viewport: { width: W, height: H } });
  for (const cam of cams) {
    await page.goto(`${base}?${qs({ cam, t: at })}`);
    await waitReady(page, '__ready');
    const name = cam.replace(/[^a-z0-9]+/gi, '_');
    const file = join(out, `${name}.png`);
    await page.screenshot({ path: file });
    report.shots.push({ cam, file: relative(process.cwd(), file) });
    report.result = await page.evaluate(() => window.__result);
  }
  await page.close();
  if (args.includes('--video')) {
    const ctx = await browser.newContext({ viewport: { width: W, height: H }, recordVideo: { dir: out, size: { width: W, height: H } } });
    const vp = await ctx.newPage();
    await vp.goto(`${base}?${qs({ cam: cams[0], play: 1 })}`);
    await waitReady(vp, '__done');
    const v = vp.video();
    await ctx.close();
    const file = join(out, `replay_seed${seed}.webm`);
    await rename(await v.path(), file);
    report.video = relative(process.cwd(), file);
  }
} finally {
  await browser.close();
  server.close();
}
console.log(JSON.stringify(report));

// Builds one trial's world: the harness's desk, cup and marble, plus whatever the scene adds through `add`.
// Runs unchanged in Node (physics trials) and in the browser (renders). THREE and CANNON are passed in.
import { TASK, rng } from './task.mjs';

export class SceneError extends Error {}

const vec = (v, n, what) => {
  if (!Array.isArray(v) || v.length !== n || !v.every(Number.isFinite)) throw new SceneError(`${what} must be an array of ${n} finite numbers`);
  return v;
};

// Source rules for scene files: one default export, no imports, no reaching outside the arguments it is given.
const FORBIDDEN = [/^\s*import\s/m, /\bimport\s*\(/, /\brequire\s*\(/, /\bglobalThis\b/, /\bwindow\b/, /\bdocument\b/,
  /\bprocess\b/, /\bfetch\b/, /\beval\b/, /\bFunction\s*\(/, /\bDate\b/, /\bperformance\b/, /\bsetTimeout\b/, /\bsetInterval\b/];

export function checkSource(src) {
  for (const re of FORBIDDEN) if (re.test(src)) throw new SceneError(`scene source uses a forbidden construct: ${re}`);
  if (!/export\s+default\s+function/.test(src)) throw new SceneError('scene must `export default function build({ THREE, add, task })`');
}

export function buildWorld({ THREE, CANNON, build, trial, graphics = true }) {
  const world = new CANNON.World({ gravity: new CANNON.Vec3(0, -9.81, 0) });
  world.broadphase = new CANNON.SAPBroadphase(world);
  world.allowSleep = false;
  world.solver.iterations = 20;
  const marbleMat = new CANNON.Material('marble');
  const pieceMat = new CANNON.Material('piece');
  world.addContactMaterial(new CANNON.ContactMaterial(marbleMat, pieceMat, {
    friction: trial.friction, restitution: trial.restitution,
  }));
  const root = new THREE.Group();
  const quat = (rot) => new THREE.Quaternion().setFromEuler(new THREE.Euler(rot[0], rot[1], rot[2], 'XYZ'));
  const material = (color) => new THREE.MeshStandardMaterial({ color, roughness: 0.6, metalness: 0.05 });
  const B = TASK.bounds, LIM = TASK.budget;
  let pieces = 0, movers = 0;
  const moverList = [];

  const place = (body, mesh, position, rotation) => {
    const q = quat(rotation);
    body.position.set(...position);
    body.quaternion.set(q.x, q.y, q.z, q.w);
    world.addBody(body);
    if (mesh) { mesh.position.set(...position); mesh.quaternion.copy(q); mesh.castShadow = mesh.receiveShadow = true; root.add(mesh); }
  };
  const inBounds = (p, what) => {
    if (p[0] < B.minX || p[0] > B.maxX || p[1] < B.minY || p[1] > B.maxY || p[2] < B.minZ || p[2] > B.maxZ)
      throw new SceneError(`${what} at [${p.map((x) => x.toFixed(3))}] is outside the allowed volume`);
  };
  const size = (s, what) => {
    vec(s, 3, `${what} size`);
    if (s.some((x) => x < LIM.minSize || x > LIM.maxSize)) throw new SceneError(`${what} size must be within ${LIM.minSize}..${LIM.maxSize} m on every axis`);
    return s;
  };
  const countPiece = (what) => {
    if (++pieces > LIM.pieces) throw new SceneError(`more than ${LIM.pieces} physical pieces (${what})`);
  };

  // Harness-owned pieces: desk top (as an infinite plane) and the cup.
  const d = TASK.desk, deskSize = [d.maxX - d.minX, 0.04, d.maxZ - d.minZ];
  const desk = new CANNON.Body({ mass: 0, type: CANNON.Body.STATIC, material: pieceMat,
    shape: new CANNON.Box(new CANNON.Vec3(deskSize[0] / 2, deskSize[1] / 2, deskSize[2] / 2)) });
  place(desk, graphics ? new THREE.Mesh(new THREE.BoxGeometry(...deskSize), material('#9a6b43')) : null, [0, -0.02, 0], [0, 0, 0]);
  const C = TASK.cup;
  const ring = C.innerRadius + C.wallThickness / 2;
  for (let i = 0; i < C.segments; i++) {
    const a = (i / C.segments) * 2 * Math.PI;
    const w = (2 * Math.PI * ring / C.segments) * 1.08;
    const p = [C.center[0] + ring * Math.cos(a), C.wallHeight / 2, C.center[2] + ring * Math.sin(a)];
    const body = new CANNON.Body({ mass: 0, type: CANNON.Body.STATIC, material: pieceMat,
      shape: new CANNON.Box(new CANNON.Vec3(C.wallThickness / 2, C.wallHeight / 2, w / 2)) });
    const mesh = graphics ? new THREE.Mesh(new THREE.BoxGeometry(C.wallThickness, C.wallHeight, w), material('#f4f1ea')) : null;
    place(body, mesh, p, [0, -a, 0]);
  }

  // The only API a scene gets. No handle on the world, the marble or time other than a mover's own path.
  const add = Object.freeze({
    box({ size: s, position, rotation = [0, 0, 0], color = '#b8b8b8' }) {
      countPiece('box'); size(s, 'box'); vec(position, 3, 'box position'); vec(rotation, 3, 'box rotation'); inBounds(position, 'box');
      const body = new CANNON.Body({ mass: 0, type: CANNON.Body.STATIC, material: pieceMat,
        shape: new CANNON.Box(new CANNON.Vec3(s[0] / 2, s[1] / 2, s[2] / 2)) });
      place(body, graphics ? new THREE.Mesh(new THREE.BoxGeometry(...s), material(color)) : null, position, rotation);
    },
    cylinder({ radius, height, position, rotation = [0, 0, 0], color = '#b8b8b8' }) {
      countPiece('cylinder'); size([radius * 2, height, radius * 2], 'cylinder'); vec(position, 3, 'cylinder position'); inBounds(position, 'cylinder');
      const body = new CANNON.Body({ mass: 0, type: CANNON.Body.STATIC, material: pieceMat,
        shape: new CANNON.Cylinder(radius, radius, height, 16) });
      place(body, graphics ? new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, height, 24), material(color)) : null, position, rotation);
    },
    mover({ size: s, path, color = '#d05a3c' }) {
      if (++movers > LIM.movers) throw new SceneError(`more than ${LIM.movers} movers`);
      size(s, 'mover');
      if (typeof path !== 'function') throw new SceneError('mover path must be a function of time t (seconds)');
      const pose = (t) => {
        const p = path(t) || {};
        return { position: vec(p.position, 3, 'mover position'), rotation: vec(p.rotation || [0, 0, 0], 3, 'mover rotation') };
      };
      const p0 = pose(0);
      inBounds(p0.position, 'mover');
      const body = new CANNON.Body({ mass: 0, type: CANNON.Body.KINEMATIC, material: pieceMat,
        shape: new CANNON.Box(new CANNON.Vec3(s[0] / 2, s[1] / 2, s[2] / 2)) });
      const mesh = graphics ? new THREE.Mesh(new THREE.BoxGeometry(...s), material(color)) : null;
      place(body, mesh, p0.position, p0.rotation);
      moverList.push({ body, mesh, pose });
    },
    decor(object3D) {
      if (!graphics) return;
      if (!object3D || !object3D.isObject3D) throw new SceneError('decor takes a THREE.Object3D');
      root.add(object3D);
    },
  });

  // Run the scene's build with a seeded Math.random so every trial builds the identical scene.
  const realRandom = Math.random;
  Math.random = rng(424242);
  try { build({ THREE, add, task: TASK }); }
  catch (e) { if (e instanceof SceneError) throw e; throw new SceneError(`scene build threw: ${e && e.message}`); }
  finally { Math.random = realRandom; }

  const M = TASK.marble;
  const marble = new CANNON.Body({ mass: M.mass, shape: new CANNON.Sphere(M.radius), material: marbleMat,
    linearDamping: 0.01, angularDamping: 0.01 });
  marble.position.set(M.start[0] + trial.startOffset[0], M.start[1], M.start[2] + trial.startOffset[2]);
  marble.velocity.set(...trial.startVelocity);
  world.addBody(marble);
  let marbleMesh = null;
  if (graphics) {
    marbleMesh = new THREE.Mesh(new THREE.SphereGeometry(M.radius, 32, 16),
      new THREE.MeshStandardMaterial({ color: '#2f7fd8', roughness: 0.15, metalness: 0.3 }));
    marbleMesh.castShadow = true; root.add(marbleMesh);
  }

  const setMovers = (t, dt) => {
    for (const m of moverList) {
      const p = m.pose(t), q = quat(p.rotation);
      const prev = m.body.position.clone(), prevQ = m.body.quaternion.clone();
      m.body.position.set(...p.position);
      m.body.quaternion.set(q.x, q.y, q.z, q.w);
      if (dt > 0) {
        m.body.velocity.set((p.position[0] - prev.x) / dt, (p.position[1] - prev.y) / dt, (p.position[2] - prev.z) / dt);
        const dq = m.body.quaternion.mult(prevQ.conjugate());
        const ang = 2 * Math.acos(Math.min(1, Math.abs(dq.w)));
        const s = Math.sqrt(Math.max(1e-12, 1 - dq.w * dq.w)) * Math.sign(dq.w || 1);
        m.body.angularVelocity.set(ang > 1e-9 ? (dq.x / s) * ang / dt : 0, ang > 1e-9 ? (dq.y / s) * ang / dt : 0, ang > 1e-9 ? (dq.z / s) * ang / dt : 0);
      }
      if (m.mesh) { m.mesh.position.set(...p.position); m.mesh.quaternion.copy(q); }
    }
  };

  return { world, root, marble, marbleMesh, movers: moverList, setMovers, pieces: () => pieces };
}

// Judge the end state: is the marble resting inside the cup?
export function judgeEnd(marble) {
  const C = TASK.cup;
  const dx = marble.position.x - C.center[0], dz = marble.position.z - C.center[2];
  const r = Math.hypot(dx, dz);
  return { success: r < C.innerRadius && marble.position.y < C.wallHeight, distToCup: r };
}

// The trial loop, shared by the Node judge and the browser viewer so a replay is the run the judge scored.
import { TASK, trial as makeTrial } from './task.mjs';
import { buildWorld, judgeEnd } from './world.mjs';

export function runTrial({ THREE, CANNON, build, seed, graphics = false, record = false, bumpOverride = null }) {
  const tr = makeTrial(seed);
  if (bumpOverride) tr.bump = bumpOverride;
  const w = buildWorld({ THREE, CANNON, build, trial: tr, graphics });
  const { world, marble } = w;
  const steps = Math.round(TASK.duration / TASK.dt);
  const every = Math.round(1 / 30 / TASK.dt);
  const track = [];
  let bumped = false, fell = false, still = 0, t = 0, maxSpeed = 0;
  const snap = () => track.push({ t: +t.toFixed(4), p: [marble.position.x, marble.position.y, marble.position.z],
    q: [marble.quaternion.x, marble.quaternion.y, marble.quaternion.z, marble.quaternion.w],
    movers: w.movers.map((m) => ({ p: [m.body.position.x, m.body.position.y, m.body.position.z],
      q: [m.body.quaternion.x, m.body.quaternion.y, m.body.quaternion.z, m.body.quaternion.w] })) });
  w.setMovers(0, 0);
  for (let i = 0; i < steps; i++) {
    t = i * TASK.dt;
    if (record && i % every === 0) snap();
    if (w.movers.length) w.setMovers(t + TASK.dt, TASK.dt);
    if (!bumped && t >= tr.bump.time) {
      marble.velocity.x += tr.bump.dv[0]; marble.velocity.y += tr.bump.dv[1]; marble.velocity.z += tr.bump.dv[2];
      bumped = true;
    }
    world.step(TASK.dt);
    const v = marble.velocity.length();
    maxSpeed = Math.max(maxSpeed, v);
    if (marble.position.y < -0.3) { fell = true; break; }
    // Early stop once the marble has rested for a second after the bump (static scenes only).
    still = v < 0.002 ? still + TASK.dt : 0;
    if (!w.movers.length && bumped && still > 1.0) break;
  }
  if (record) snap();
  const end = judgeEnd(marble);
  return {
    result: {
      seed, success: !fell && end.success, fell, distToCup: +end.distToCup.toFixed(4), simulatedSeconds: +t.toFixed(2),
      final: [marble.position.x, marble.position.y, marble.position.z].map((x) => +x.toFixed(4)),
      maxSpeed: +maxSpeed.toFixed(3), pieces: w.pieces(), bumpTime: +tr.bump.time.toFixed(2),
    },
    track, world: w,
  };
}

// Browser viewer: rebuilds the scene, re-runs the same trial the judge ran, and renders it.
// URL: /harness/view.html?scene=/scenes/x.js&seed=1&cam=overview | cam=az,el,dist &t=end|seconds &play=1 &w=1280&h=720
import * as THREE from 'three';
import * as CANNON from 'cannon-es';
import { TASK, VAL_CAMERAS } from './task.mjs';
import { checkSource } from './world.mjs';
import { runTrial } from './trialrun.mjs';

const q = new URLSearchParams(location.search);
const W = +(q.get('w') || 1280), H = +(q.get('h') || 720);

export function cameraFor(spec) {
  const named = VAL_CAMERAS.find((c) => c.name === spec);
  if (named) return named;
  const [az, el, dist] = String(spec).split(',').map(Number); // degrees, degrees, metres around the desk centre
  const a = az * Math.PI / 180, e = el * Math.PI / 180;
  return { name: spec, position: [dist * Math.cos(e) * Math.sin(a), 0.2 + dist * Math.sin(e), dist * Math.cos(e) * Math.cos(a)], target: [0, 0.2, 0] };
}

async function main() {
  const sceneUrl = q.get('scene');
  const src = await (await fetch(sceneUrl, { cache: 'no-store' })).text();
  checkSource(src);
  const build = (await import(sceneUrl + '?v=' + Date.now())).default;
  const seed = +(q.get('seed') || 1);
  const bump = q.get('bump') ? JSON.parse(q.get('bump')) : null;
  const { result, track, world } = runTrial({ THREE, CANNON, build, seed, graphics: true, record: true, bumpOverride: bump });
  window.__result = result;

  const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
  renderer.setSize(W, H); renderer.setPixelRatio(1);
  renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  document.body.appendChild(renderer.domElement);
  const scene = new THREE.Scene();
