export default function build({ THREE, add, task }) {
  // Colours for a warm wood + brass + forest green desk toy aesthetic
  const cWood = '#c89662';
  const cRail = '#3b4d3e';
  const cAccent = '#d4883a';
  const cMetal = '#7a8288';
  const cCatch = '#2c3e50';

  // Helper to place a tilted trough (floor + left wall + right wall)
  // Using Euler XYZ: first rotate around X (cross-tilt), then Y (yaw), then Z (slope along local X)
  // Actually, to make rotation super clean: if yaw is ry, and pitch along local X is rz:
  // In Euler XYZ, if rx = 0, R = Rx(0) * Ry(ry) * Rz(rz).
  // That means Rz(rz) happens FIRST in local coordinates (tilting the local X axis up/down),
  // and THEN Ry(ry) rotates that tilted ramp in the horizontal plane!
  // Let's verify: v_world = Ry(ry) * Rz(rz) * v_local.
  // Yes! In THREE.Euler(0, ry, rz, 'XYZ'), intrinsic XYZ is extrinsic ZYX, or matrix M = Mx * My * Mz.
  // With rx = 0, M = My(ry) * Mz(rz).
  // So a point in local space is first tilted by rz around Z (so local +X goes up/down by sin(rz), and local Z stays horizontal!),
  // and then rotated around world Y by ry!
  // That makes building a sloped channel along any horizontal direction (ry) with zero cross-tilt trivial!

  function addChannel({ x1, y1, z1, x2, y2, z2, width = 0.12, wallH = 0.08, thick = 0.016, floorColor = cWood, wallColor = cRail, leftWall = true, rightWall = true }) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const dz = z2 - z1;
    const horizLen = Math.hypot(dx, dz);
    const len = Math.hypot(horizLen, dy);
    // Direction in XZ plane: local +X mapped by Ry(ry) goes to (cos(ry), 0, -sin(ry)).
    // Wait: Ry(ry) * [1, 0, 0]^T = [cos(ry), 0, -sin(ry)]^T.
    // So to point along (dx, dz), we want cos(ry) = dx/horizLen, -sin(ry) = dz/horizLen => ry = Math.atan2(-dz, dx).
    const ry = Math.atan2(-dz, dx);
    // Rz(rz) * [1, 0, 0]^T = [cos(rz), sin(rz), 0]^T.
    // So sin(rz) = dy / len => rz = Math.atan2(dy, horizLen).
    const rz = Math.atan2(dy, horizLen);

    const cx = (x1 + x2) / 2;
    const cy = (y1 + y2) / 2;
    const cz = (z1 + z2) / 2;

    // Local up vector after Rz(rz) is [-sin(rz), cos(rz), 0], and after Ry(ry) is:
    const ux = -Math.sin(rz) * Math.cos(ry);
    const uy = Math.cos(rz);
    const uz = Math.sin(rz) * Math.sin(ry);

    // Local +Z vector after Ry(ry)*Rz(rz) is [sin(ry), 0, cos(ry)]
    const zx = Math.sin(ry);
    const zz = Math.cos(ry);

    // Floor
    add.box({
      size: [len, thick, width],
      position: [cx, cy, cz],
      rotation: [0, ry, rz],
      color: floorColor,
    });

    const halfW = (width - thick) / 2;
    const wallYOff = (thick + wallH) / 2;

    if (leftWall) {
      // -Z side wall
      add.box({
        size: [len, wallH, thick],
        position: [
          cx - halfW * zx + wallYOff * ux,
          cy + wallYOff * uy,
          cz - halfW * zz + wallYOff * uz,
        ],
        rotation: [0, ry, rz],
        color: wallColor,
      });
    }
    if (rightWall) {
      // +Z side wall
      add.box({
        size: [len, wallH, thick],
        position: [
          cx + halfW * zx + wallYOff * ux,
          cy + wallYOff * uy,
          cz + halfW * zz + wallYOff * uz,
        ],
        rotation: [0, ry, rz],
        color: wallColor,
      });
    }
  }

  // 1. Catch basin + Ramp 1 (from drop [-0.85, 0.8, -0.3] towards [-0.25, 0.44, -0.3])
  // Backstop behind drop at x = -0.98
  add.box({
    size: [0.02, 0.16, 0.24],
    position: [-0.97, 0.70, -0.3],
    rotation: [0, 0, 0],
    color: cRail,
  });

  // Ramp 1: x from -0.98 to -0.22, y from 0.64 to 0.44, z = -0.3 (3 pieces)
  addChannel({
    x1: -0.98, y1: 0.64, z1: -0.30,
    x2: -0.20, y2: 0.44, z2: -0.30,
    width: 0.22, wallH: 0.11, thick: 0.016,
  });

  // Turn 1 catcher wall at x = -0.12, deflecting marble toward +Z onto Ramp 2 (1 piece)
  add.box({
    size: [0.02, 0.18, 0.28],
    position: [-0.14, 0.45, -0.22],
    rotation: [0, -0.45, 0],
    color: cAccent,
  });

  // 2. Ramp 2: from [-0.20, 0.40, -0.32] to [0.35, 0.24, 0.12] (3 pieces)
  addChannel({
    x1: -0.26, y1: 0.41, z1: -0.32,
    x2: 0.36, y2: 0.23, z2: 0.12,
    width: 0.16, wallH: 0.10, thick: 0.016,
  });

  // Turn 2 bumper wall at [0.44, 0.25, 0.16] deflecting into Ramp 3 (1 piece)
  add.box({
    size: [0.02, 0.16, 0.24],
    position: [0.43, 0.25, 0.15],
    rotation: [0, 0.35, 0],
    color: cAccent,
  });

  // 3. Ramp 3: from [0.32, 0.19, 0.12] to [0.74, 0.085, 0.30] leading straight to the cup center [0.8, 0, 0.3] (3 pieces)
  addChannel({
    x1: 0.28, y1: 0.20, z1: 0.12,
    x2: 0.73, y2: 0.08, z2: 0.30,
    width: 0.14, wallH: 0.09, thick: 0.015,
  });

  // 4. Cup trap & backstop around [0.8, 0, 0.3]
  // Backstop behind the cup (at +X, +Z side of cup) to stop the marble directly above the cup center
  add.box({
    size: [0.02, 0.18, 0.18],
    position: [0.86, 0.11, 0.32],
    rotation: [0, -0.38, 0.15], // slightly tilted inward so rebound goes straight down into cup
    color: cCatch,
  });

  // Side cheek left (-Z side of cup entry)
  add.box({
    size: [0.16, 0.14, 0.02],
    position: [0.79, 0.10, 0.22],
    rotation: [0.15, -0.38, 0],
    color: cCatch,
  });

  // Side cheek right (+Z side of cup entry)
  add.box({
    size: [0.16, 0.14, 0.02],
    position: [0.76, 0.10, 0.38],
    rotation: [-0.15, -0.38, 0],
    color: cCatch,
  });

  // Anti-bump lid/baffle directly over the cup at y = 0.11 (leaves entry gap on the -X/-Z side from Ramp 3,
  // but blocks upward/sideways escapes if a bump hits after the marble is in the cup)
  add.box({
    size: [0.11, 0.016, 0.13],
    position: [0.82, 0.095, 0.31],
    rotation: [0, -0.38, -0.25],
    color: cMetal,
  });
}

